/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `producto` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `extract` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb3_unicode_ci,
  `destacado` tinyint(1) NOT NULL DEFAULT '0',
  `precio` decimal(10,2) NOT NULL,
  `en_oferta` tinyint(1) NOT NULL DEFAULT '0',
  `precio_oferta` decimal(10,2) DEFAULT NULL,
  `porcentaje_oferta` decimal(10,2) DEFAULT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `sku` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `peso_empaque` decimal(10,2) DEFAULT NULL,
  `devolucion` tinyint(1) NOT NULL DEFAULT '1',
  `tipo_vendedor` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'Vendedor verificado',
  `garantia_entrega` tinyint(1) NOT NULL DEFAULT '1',
  `envio_gratis` tinyint(1) NOT NULL DEFAULT '1',
  `imagen` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `especificaciones` text COLLATE utf8mb3_unicode_ci,
  `album` text COLLATE utf8mb3_unicode_ci,
  `manuales` text COLLATE utf8mb3_unicode_ci,
  `slug` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `categoria_id` bigint unsigned DEFAULT NULL,
  `brand_id` bigint unsigned DEFAULT NULL,
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `meta_title` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb3_unicode_ci,
  `meta_keywords` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `attributes` json DEFAULT NULL,
  `especificacion` text COLLATE utf8mb3_unicode_ci,
  `order` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_categoria_id_foreign` (`categoria_id`),
  KEY `products_brand_id_foreign` (`brand_id`),
  CONSTRAINT `products_brand_id_foreign` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`),
  CONSTRAINT `products_categoria_id_foreign` FOREIGN KEY (`categoria_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

